-- Rich invitation email. Generated by email/build_email.py from email/invite.html.
create or replace function public.p2p_esc(t text) returns text language sql immutable as $$
  select replace(replace(replace(replace(coalesce(t, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;'), '"', '&quot;')
$$;

create or replace function public.invite_email_html(p_to text, p_role text, p_inviter text, p_note text, p_title text) returns text
language plpgsql immutable set search_path = public as $fn$
declare
  t text := '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light only"><title>Proof to Profit</title></head><body style="margin:0;padding:0;background:#F3EEE6;"><div style="display:none;max-height:0;overflow:hidden;opacity:0;color:#F3EEE6;">{{PRE}}</div><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F3EEE6;"><tr><td align="center" style="padding:26px 12px;"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#FBF8F3;border-radius:22px;overflow:hidden;box-shadow:0 18px 50px -20px rgba(20,22,26,.35);"><tr><td bgcolor="#14161A" style="padding:18px 28px;background:#14161A;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="padding-right:10px;"><img src="https://proof2profit.site/assets/logo.png" width="34" height="34" alt="" style="display:block;border-radius:8px;"></td><td style="font-family:''Trebuchet MS'',Arial,sans-serif;font-size:19px;font-weight:bold;color:#F3EFE8;letter-spacing:-.2px;">Proof <span style="color:#F69500;">to</span> Profit</td></tr></table></td></tr><tr><td bgcolor="#14161A" style="line-height:0;font-size:0;background:#14161A;"><img src="https://proof2profit.site/assets/invite-hero.gif" width="600" alt="Proof to Profit turns your customer reviews into a plan: ratings by topic, what guests love and what to fix first." style="display:block;width:100%;max-width:600px;height:auto;"></td></tr><tr><td style="padding:34px 32px 6px;font-family:Arial,Helvetica,sans-serif;"><p style="margin:0 0 10px;font-size:11px;font-weight:bold;letter-spacing:2px;color:#A85A00;">YOU&rsquo;RE INVITED</p><h1 style="margin:0 0 14px;font-family:''Trebuchet MS'',Arial,sans-serif;font-size:31px;line-height:1.1;color:#14161A;letter-spacing:-.5px;">{{HEAD}}</h1><p style="margin:0;font-size:16px;line-height:1.6;color:#5E5A54;">{{INTRO}}</p></td></tr><tr><td style="padding:22px 32px 4px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="4" bgcolor="#F69500" style="background:#F69500;border-radius:4px;"></td><td bgcolor="#FDEBCF" style="background:#FDEBCF;border-radius:0 14px 14px 0;padding:16px 18px;font-family:Arial,Helvetica,sans-serif;"><span style="display:inline-block;background:#14161A;color:#FFB438;font-size:11px;font-weight:bold;letter-spacing:1.4px;padding:4px 10px;border-radius:99px;">{{ROLE}}</span><p style="margin:10px 0 0;font-size:14.5px;line-height:1.55;color:#14161A;">{{BLURB}}</p></td></tr></table></td></tr>{{NOTEROW}}<tr><td style="padding:26px 32px 4px;font-family:Arial,Helvetica,sans-serif;"><p style="margin:0 0 14px;font-family:''Trebuchet MS'',Arial,sans-serif;font-size:18px;font-weight:bold;color:#14161A;">Up and running in a minute</p><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td width="40" valign="top" style="padding-bottom:14px;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td width="28" height="28" align="center" bgcolor="#F69500" style="background:#F69500;border-radius:14px;font-size:14px;font-weight:bold;color:#14161A;">1</td></tr></table></td><td style="padding-bottom:14px;font-size:15px;line-height:1.5;color:#14161A;"><b>Sign in with Google</b> using this email address:<br><span style="color:#008CBB;font-weight:bold;">{{TO}}</span></td></tr><tr><td width="40" valign="top" style="padding-bottom:14px;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td width="28" height="28" align="center" bgcolor="#008CBB" style="background:#008CBB;border-radius:14px;font-size:14px;font-weight:bold;color:#ffffff;">2</td></tr></table></td><td style="padding-bottom:14px;font-size:15px;line-height:1.5;color:#14161A;">{{STEP2}}</td></tr><tr><td width="40" valign="top"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td width="28" height="28" align="center" bgcolor="#7FA10A" style="background:#7FA10A;border-radius:14px;font-size:14px;font-weight:bold;color:#ffffff;">3</td></tr></table></td><td style="font-size:15px;line-height:1.5;color:#14161A;">{{STEP3}}</td></tr></table></td></tr><tr><td align="center" style="padding:30px 32px 10px;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td align="center" bgcolor="#F69500" style="background:#F69500;border-radius:14px;"><a href="https://app.proof2profit.site" style="display:inline-block;padding:17px 38px;font-family:''Trebuchet MS'',Arial,sans-serif;font-size:17px;font-weight:bold;color:#14161A;text-decoration:none;">Accept your invitation &rarr;</a></td></tr></table><p style="margin:14px 0 0;font-family:Arial,Helvetica,sans-serif;font-size:12.5px;color:#8a857d;">Or open <a href="https://app.proof2profit.site" style="color:#A85A00;">app.proof2profit.site</a></p></td></tr><tr><td style="padding:26px 32px 30px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #E6DFD3;"><tr><td style="padding-top:18px;font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.6;color:#8a857d;">Proof to Profit is invite-only right now, so this link only works for {{TO}}. Not expecting this? You can safely ignore it. Nothing happens until you sign in.<br><a href="https://proof2profit.site" style="color:#A85A00;">proof2profit.site</a> &middot; AI review intelligence for local businesses</td></tr></table></td></tr></table></td></tr></table></body></html>';
  who text := coalesce(nullif(trim(p_inviter), ''), 'The Proof to Profit team');
  role_label text; head text; intro text; blurb text; step2 text; step3 text; notes text := '';
begin
  role_label := case p_role when 'super' then 'SUPER USER' when 'admin' then 'ADMIN' when 'sales' then 'SALES' when 'member' then 'TEAM MEMBER' else 'BUSINESS OWNER' end;
  head := case p_role
    when 'member' then 'Join the team on Proof to Profit'
    when 'owner' then 'See what your customers really think'
    else 'Welcome to Proof to Profit' end;
  intro := public.p2p_esc(who) || ' has invited you to Proof to Profit, the AI that reads a business&rsquo;s reviews and turns them into scores, fixes and a plan for growing revenue.';
  blurb := case p_role
    when 'super' then 'You have full control of the platform: invitations, roles and everything else.'
    when 'admin' then 'You can invite and manage sales people and business owners, and see every invitation.'
    when 'sales' then 'You can invite business owners to Proof to Profit and see who has joined.'
    when 'member' then 'You are joining ' || public.p2p_esc(who) || '&rsquo;s team' || case when coalesce(trim(p_title), '') <> '' then ' as ' || public.p2p_esc(p_title) else '' end || '. Analyze businesses, save reports and track what changes over time.'
    else 'Analyze any business, save reports, track changes over time, and add your own managers and marketing crew to your team.' end;
  if p_role in ('super', 'admin', 'sales') then
    step2 := '<b>Click your name</b> at the top left, then <b>Invitations</b>.';
    step3 := '<b>Invite people</b> and watch them join. They get this same welcome.';
  else
    step2 := '<b>Paste a Google Maps link</b> or just a business name and city.';
    step3 := '<b>See the plan:</b> scores by topic, what guests love and what to fix first.';
  end if;
  if coalesce(trim(p_note), '') <> '' then
    notes := '<tr><td style="padding:16px 32px 0;font-family:Arial,Helvetica,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="background:#ffffff;border:1px solid #E6DFD3;border-radius:14px;padding:14px 16px;font-size:14px;line-height:1.55;color:#5E5A54;"><b style="color:#14161A;">A note from ' || public.p2p_esc(who) || ':</b><br>&ldquo;' || public.p2p_esc(p_note) || '&rdquo;</td></tr></table></td></tr>';
  end if;
  t := replace(t, '{PRE}', public.p2p_esc(who) || ' invited you. Sign in with Google to get started.');
  t := replace(t, '{HEAD}', head);
  t := replace(t, '{INTRO}', intro);
  t := replace(t, '{ROLE}', role_label);
  t := replace(t, '{BLURB}', blurb);
  t := replace(t, '{NOTEROW}', notes);
  t := replace(t, '{STEP2}', step2);
  t := replace(t, '{STEP3}', step3);
  t := replace(t, '{TO}', public.p2p_esc(p_to));
  return t;
end $fn$;

create or replace function public.trg_allowed_email() returns trigger
language plpgsql security definer set search_path = public as $$
declare who text;
begin
  select coalesce(nullif(trim(p.display_name), ''), split_part(new.invited_by, '@', 1)) into who
  from auth.users u left join public.profiles p on p.user_id = u.id where lower(u.email) = lower(new.invited_by) limit 1;
  who := coalesce(who, nullif(split_part(coalesce(new.invited_by, ''), '@', 1), ''));
  perform public.queue_email(null, new.email, 'welcome',
    case when who is null then 'You are invited to Proof to Profit' else who || ' invited you to Proof to Profit' end,
    public.invite_email_html(new.email, new.role, who, new.note, new.title));
  return new;
end $$;
